151:         allSelected: hasHouse && allSelected,
152:         anySelected,
153:         indeterminate: anySelected && !(hasHouse && allSelected)
154:       }
155:     },
156:     rebuildGlobalCheckState(byId, treeData, treeKey) {
157:       let allSelected = true
158:       let anySelected = false
159: 
160:       treeData.forEach((building) => {
161:         const state = byId[building[treeKey]] || {
162:           hasHouse: false,
163:           allSelected: false,
164:           anySelected: false,
165:           indeterminate: false
166:         }
167:         if (!state.hasHouse) {
