176:             anySelected = true
177:           }
178:         }
179:       })
180: 
181:       const isAllSelected = treeData.length > 0 && allSelected
182:       return {
183:         isAllSelected,
184:         isAllIndeterminate: anySelected && !isAllSelected
185:       }
