  const prevIds = this._lastListSelectedIds || new Set()
  const affectedBuildingIds = new Set()
  this.forEachHouseInTreeData((house, { building }) => {
    const shouldCheck = selectedIds.has(house.houseId)
    const wasChecked = prevIds.has(house.houseId)
    if (shouldCheck !== wasChecked) {
      house.checked = shouldCheck ? '1' : '0'
