onListSelectionChange(selection) {
  if (this.isSyncingSelection) return
  // 列表（分页）选择变化：只更新「当前页显示房屋」的勾选状态，其余页/楼幢的勾选保持不动，
  // 避免用当前页选择覆盖其它页勾选；同时把缓存刷新限制在受影响的楼幢内，
  // 避免每次点击遍历全部楼幢与房屋、重建全量缓存导致大型小区卡死。
  const selectedIds = new Set(selection.map((item) => item.houseId))
  const pageHouseIds = new Set((this.$refs.listTable?.tableData || []).map((row) => row.houseId))
  const affectedBuildingIds = new Set()
  this.forEachHouseInTreeData((house) => {
    if (!pageHouseIds.has(house.houseId)) return
    const shouldCheck = selectedIds.has(house.houseId)
    const nextVal = shouldCheck ? '1' : '0'
    if (house.checked !== nextVal) {
      house.checked = nextVal
      const bid = this.buildingCheckCache.treeKey
        ? undefined
        : undefined
      // 记录受影响楼幢（见下方 building 上下文）
    }
  })
  // 依据当前页房屋定位其所属楼幢，仅刷新这些楼幢的勾选状态缓存
  const { treeData } = this.getDialogTreeMeta()
  treeData.forEach((building) => {
    let touched = false
    this.forEachHouseInBuilding(building, (house) => {
      if (pageHouseIds.has(house.houseId) && selectedIds.has(house.houseId)) touched = true
    })
    if (touched) affectedBuildingIds.add(building[this.buildingCheckCache.treeKey])
  })
  if (affectedBuildingIds.size) {
    this.notifyBuildingSelectChange([...affectedBuildingIds])
  }
  this.$nextTick(() => {
    this.syncListSelection?.()
  })
},

