mcp_gateway {
  "server": "dbx",
  "tool": "dbx_execute_query",
  "arguments": {
    "connection_name": "新禅道",
    "sql": "INSERT INTO zt_action (objectType,objectID,product,project,execution,actor,action,date,comment,files,extra,`read`,efforted,vision) VALUES ('bug',6467,'<product>','<project>','<execution>','tiany','resolved',NOW(),'<p><strong>根因：</strong>「选择户室」弹窗列表视图由提交 adbd25a2f(#2035) 引入回归。该提交把列表数据源从「仅当前楼幢」改为「汇总所有楼幢全部房屋」（<code>flattenAllBuildingsHouses</code>），并且让扁平化结果依赖勾选版本号、每次勾选/加载都遍历全部楼幢房屋重新深拷贝对象，勾选同步也每次重建全量勾选缓存。惠山二期小区楼幢/户数较多时，打开弹窗及选择户室时主线程被大量同步计算阻塞，导致「楼幢筛选」一直转圈、页面卡死、点击无响应。</p>\n<p><strong>修复：</strong>重构 <code>views/autonomy/mixins/decisionRangeBuildingSelectMixins.js</code>（option/multiply/general/repair 等 6 个表决页共用）：</p>\n<ol>\n<li>新增 <code>treeDataVersion</code>，仅在树加载完成/切换楼幢等结构变化时自增；扁平化结果按该版本缓存，勾选变化不再触发重新扁平化全量房屋。</li>\n<li><code>onListSelectionChange</code> 改为只更新「当前页显示房屋」的勾选（按 houseId 增量），不再用当前页选择覆盖其它页/其它楼幢的勾选（同时修复了跨页勾选被清空的隐患）。</li>\n<li>勾选缓存刷新 <code>refreshBuildingCheckCache</code> 仅刷新受影响的楼幢，不再每次 O(全部楼幢×房屋)重建。</li>\n</ol>\n<p>保留 #2035「列表视图汇总多楼幢房屋、跨楼幢勾选记忆、可提交」的功能不变，仅消除同步重算造成的卡顿。</p>\n<p><strong>验证：</strong></p>\n<ul>\n<li>npx eslint 通过；生产构建成功（version 2.6.1，buildTime 2026-11-11 14:04:44，gitHash daf1a2956，分支 develop/v2.6.2-huishan）。</li>\n<li>已部署本地 nginx 站点 http://127.0.0.1:8119 （root -> D:/repository/惠山二期G/dist），首页及全部 JS/CSS 资源均 200。</li>\n<li>交互式 E2E（登录惠山后端实际操作选择户室）未执行——本地无该后端登录态。</li>\n</ul>',NULL,'fixed',0,0,'rnd');",
    "session_id": "<session_id>"
  }
}
